import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"STAY_WORKER_ENABLED=false","RAIL_TICKET_WORKER_ENABLED=false","travbook.payments.refund-worker-enabled=false"})
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@Import(ReviewIntegrationTest.TimeConfig.class)
@Testcontainers
class ReviewIntegrationTest {
 static final TestIssuer issuer=new TestIssuer();@Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("travbook.oidc-issuer",issuer::url);r.add("travbook.local-identity",()->true);}
 @TestConfiguration static class TimeConfig{@Bean @Primary MutableClock testClock(){return new MutableClock();}}
 static class MutableClock extends Clock{volatile Instant now=Instant.now();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return Clock.fixed(now,zone);}public Instant instant(){return now;}}
 @Autowired MutableClock clock;@Autowired RailTickets tickets;@Autowired DiscoverTrains trains;@Autowired Customers customers;@Autowired ProcessRailTickets worker;@Autowired RailTicketStore store;@Autowired RailTicketSelection selections;@Autowired RailTicketEffects effects;@Autowired RailReservations supplier;@Autowired PaymentRefunds refunds;@Autowired com.travbook.payments.application.port.in.PaymentOperations payments;@Autowired JdbcClient jdbc;@Autowired ObjectMapper json;@LocalServerPort int port;
 @Autowired com.travbook.operations.application.port.in.Operations operations;
 @TempDir Path temp;static final AtomicInteger day=new AtomicInteger(5);CustomerIdentity identity;UUID owner;String token;final HttpClient http=HttpClient.newHttpClient();
 @BeforeEach void reset()throws Exception{clock.now=Instant.now();identity=new CustomerIdentity(issuer.url(),"rail-ticket-"+UUID.randomUUID());owner=customers.resolve(identity).id();token=issuer.token(identity.subject(),"bookings:read bookings:write");}
 @AfterAll static void closeIssuer(){issuer.close();}
 String key(){return UUID.randomUUID().toString();}UUID correlation(){return UUID.randomUUID();}
 RailTickets.QuoteDetails quote(){return quote(Rail.TravelClass.SL,1);}
 RailTickets.QuoteDetails quote(Rail.TravelClass type,int count){var date=LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(day.incrementAndGet());return quoteAt(date,type,count);}
 RailTickets.QuoteDetails quoteAt(LocalDate date,Rail.TravelClass type,int count){var p=trains.search(new Rail.Criteria("NDLS","MMCT",date,Rail.Quota.GENERAL));var j=p.items().stream().filter(v->v.departure().getHour()==8).findFirst().orElseThrow();return tickets.quote(identity,j.id(),type,Rail.Quota.GENERAL,"NDLS",people(count),key(),correlation());}
 List<Passenger> people(int count){return java.util.stream.IntStream.range(0,count).mapToObj(i->new Passenger("Alex "+(char)('A'+i),"Example",LocalDate.parse("1990-01-01"),Berth.LOWER)).toList();}
 Booking book(RailTickets.QuoteDetails q,Scenario scenario){tickets.accept(identity,q.quote().id(),1,true,key(),correlation());return tickets.book(identity,q.quote().id(),1,scenario,true,key(),correlation());}
 void due(UUID id){jdbc.sql("update rail_ticket_work set next_at=clock_timestamp()-interval '1 second',lease_until=null where booking_id=:id and state in('READY','RUNNING')").param("id",id).update();}
 Booking finish(UUID id){for(int i=0;i<30;i++){var b=tickets.get(identity,id);if(b.terminal())return b;due(id);worker.tick();refunds.settleNext();}throw new AssertionError("Workflow did not finish");}
 int count(String table,String column,UUID id){return jdbc.sql("select count(*) from "+table+" where "+column+"=:id").param("id",id).query(Integer.class).single();}
 HttpResponse<String> call(String method,String path,String auth,String key,Object body)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).timeout(Duration.ofSeconds(10));if(auth!=null)r.header("Authorization","Bearer "+auth);if(key!=null)r.header("Idempotency-Key",key);if(method.equals("POST"))r.header("Content-Type","application/json").POST(body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));else r.GET();return http.send(r.build(),HttpResponse.BodyHandlers.ofString());}

 String operator(String name)throws Exception{return issuer.token(name,"",Map.of("travbook_roles",List.of("operations_reconcile"),"amr",List.of("pwd","otp"),"auth_time",Instant.now().getEpochSecond()));}
 Booking reviewed(boolean receipt){var b=book(quote(),Scenario.RESERVATION_RESPONSE_LOST);worker.tick();worker.tick();var claim=store.claim().orElseThrow();assertThat(claim.booking().id()).isEqualTo(b.id());if(receipt)assertThatThrownBy(()->effects.execute(claim.booking(),Step.RESERVE)).isInstanceOf(IllegalStateException.class);assertThat(store.complete(claim,claim.booking().review(clock.instant()))).isTrue();return tickets.get(identity,b.id());}
 @Test void signedRoleAndRecentMfaAreRequiredForEveryOperatorRead()throws Exception{String path="/api/v1/operations/reviews/RAIL";assertThat(call("GET",path,null,null,null).statusCode()).isEqualTo(401);assertThat(call("GET",path,token,null,null).statusCode()).isEqualTo(403);for(var claims:List.of(Map.<String,Object>of("travbook_roles",List.of("operations_reconcile")),Map.<String,Object>of("travbook_roles",List.of("operations_reconcile"),"amr",List.of("mfa"),"auth_time",Instant.now().minusSeconds(601).getEpochSecond()),Map.<String,Object>of("amr",List.of("mfa"),"auth_time",Instant.now().getEpochSecond())))assertThat(call("GET",path,issuer.token("operator","",claims),null,null).statusCode()).isEqualTo(403);assertThat(call("GET",path,operator("allowed"),null,null).statusCode()).isEqualTo(200);}
 @Test void receiptBackedRecoveryIsAuditedIdempotentAndNeverDuplicatesCapture()throws Exception{var b=reviewed(true);String operator=operator("allowed"),key=key(),path="/api/v1/operations/reviews/RAIL/"+b.id()+"/resume";var body=Map.of("version",b.version(),"reason","PROVIDER_STATUS_AVAILABLE","consent",true);var r=call("POST",path,operator,key,body);assertThat(r.statusCode()).as(r.body()).isEqualTo(202);var action=json.readTree(r.body());assertThat(action.get("bookingId").asString()).isEqualTo(b.id().toString());assertThat(count("rail_ticket_recovery_action","booking_id",b.id())).isEqualTo(1);var done=finish(b.id());assertThat(done.status()).isEqualTo(Status.ISSUED);assertThat(count("rail_provider_operation","reservation_id",b.id())).isEqualTo(1);assertThat(count("payment_journal","payment_id",b.id())).isEqualTo(2);assertThat(call("POST",path,operator,key,body).body()).isEqualTo(r.body());assertThat(call("POST",path,operator,key,Map.of("version",b.version(),"reason","RETRY_AFTER_OUTAGE","consent",true)).statusCode()).isEqualTo(409);assertThat(call("POST",path,operator,key(),body).statusCode()).isEqualTo(409);assertThatThrownBy(()->jdbc.sql("update rail_ticket_recovery_action set actor='changed' where booking_id=:id").param("id",b.id()).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(tickets.timeline(identity,b.id()).stream().map(e->e.eventType())).contains("RailReconciliationResumed");assertThat(call("GET","/api/v1/operations/reviews/RAIL/"+b.id(),operator,null,null).body()).doesNotContain("Alex","1990-01-01",identity.subject());}
 @Test void missingEvidenceDoesNotReplayAnEffectiveOperation()throws Exception{var b=reviewed(false);var r=call("POST","/api/v1/operations/reviews/RAIL/"+b.id()+"/resume",operator("ops"),key(),Map.of("version",b.version(),"reason","RETRY_AFTER_OUTAGE","consent",true));assertThat(r.statusCode()).isEqualTo(409);assertThat(count("rail_provider_operation","reservation_id",b.id())).isZero();assertThat(count("rail_ticket_recovery_action","booking_id",b.id())).isZero();assertThat(tickets.get(identity,b.id()).status()).isEqualTo(Status.REVIEW);}
 @Test void concurrentOperatorsCannotResumeTheSameVersionTwice()throws Exception{var b=reviewed(true);List<Boolean> results;try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.<Callable<Boolean>>of(()->resume(b,"a".repeat(64)),()->resume(b,"b".repeat(64))));results=List.of(calls.get(0).get(),calls.get(1).get());}assertThat(results.stream().filter(v->v).count()).isEqualTo(1);assertThat(count("rail_ticket_recovery_action","booking_id",b.id())).isEqualTo(1);assertThat(finish(b.id()).status()).isEqualTo(Status.ISSUED);}
 boolean resume(Booking b,String actor){try{operations.resume(com.travbook.shared.domain.Recovery.Kind.RAIL,b.id(),b.version(),actor,com.travbook.shared.domain.Recovery.Reason.PROVIDER_STATUS_AVAILABLE,true,key(),correlation());return true;}catch(DomainFailure e){assertThat(e.code()).isEqualTo(DomainFailure.Code.BOOKING_CONFLICT);return false;}}
 @Test void auditAndOutboxFailureRollBackResumption(){var b=reviewed(true);jdbc.sql("create function fail_recovery_event() returns trigger language plpgsql as $$ begin raise exception 'Injected event failure'; end $$").update();jdbc.sql("create trigger fail_recovery_event before insert on rail_ticket_outbox for each row execute function fail_recovery_event()").update();try{assertThatThrownBy(()->resume(b,"a".repeat(64))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(tickets.get(identity,b.id()).version()).isEqualTo(b.version());assertThat(count("rail_ticket_recovery_action","booking_id",b.id())).isZero();assertThat(jdbc.sql("select state from rail_ticket_work where booking_id=:id").param("id",b.id()).query(String.class).single()).isEqualTo("REVIEW");}finally{jdbc.sql("drop trigger fail_recovery_event on rail_ticket_outbox").update();jdbc.sql("drop function fail_recovery_event()").update();}assertThat(resume(b,"a".repeat(64))).isTrue();assertThat(finish(b.id()).status()).isEqualTo(Status.ISSUED);}
 @Test void recoveryBudgetAndLegacyMissingCheckpointFailClosed(){var b=reviewed(true);for(int i=0;i<3;i++){assertThat(resume(b,"a".repeat(64))).isTrue();var claim=store.claim().orElseThrow();store.complete(claim,claim.booking().review(clock.instant()));b=tickets.get(identity,b.id());}assertThat(store.review(b.id()).recoverable()).isFalse();assertThat(resume(b,"a".repeat(64))).isFalse();assertThat(count("rail_provider_operation","reservation_id",b.id())).isEqualTo(1);
  var legacy=book(quote(),Scenario.SUCCESS);jdbc.sql("update rail_ticket_booking set status='REVIEW',version=version+1,payload=jsonb_set(jsonb_set(jsonb_set(payload,'{status}','\"REVIEW\"'),'{step}','\"REVIEW\"'),'{version}',to_jsonb(version+1)) where id=:id").param("id",legacy.id()).update();jdbc.sql("update rail_ticket_work set state='REVIEW' where booking_id=:id").param("id",legacy.id()).update();assertThat(store.review(legacy.id()).recoverable()).isFalse();assertThat(resume(tickets.get(identity,legacy.id()),"a".repeat(64))).isFalse();
 }

 Booking legacy(Booking b,boolean captureUnknown){var node=(tools.jackson.databind.node.ObjectNode)json.valueToTree(b);node.put("version",b.version()+1);node.put("status","REVIEW");node.put("step","REVIEW");node.put("failureCode","RECONCILIATION_REQUIRED");if(captureUnknown)node.put("payment","AUTHORIZED");jdbc.sql("update rail_ticket_booking set version=version+1,status='REVIEW',payload=cast(:payload as jsonb) where id=:id").param("id",b.id()).param("payload",json.writeValueAsString(node)).update();jdbc.sql("update rail_ticket_work set state='REVIEW',lease_token=null,lease_until=null where booking_id=:id").param("id",b.id()).update();return tickets.get(identity,b.id());}
 @Test void legacyFulfilmentUsesCurrentProofAndNeverRepeatsEffects()throws Exception{var b=legacy(finish(book(quote(),Scenario.SUCCESS).id()),true);String path="/api/v1/operations/reviews/RAIL/"+b.id()+"/reconcile-legacy",key=key(),ops=operator("legacy-ops");var body=Map.of("version",b.version(),"reason","PROVIDER_STATUS_AVAILABLE","consent",true);assertThat(call("POST",path,token,key,body).statusCode()).isEqualTo(403);var r=call("POST",path,ops,key,body);assertThat(r.statusCode()).as(r.body()).isEqualTo(202);assertThat(call("POST",path,ops,key,body).body()).isEqualTo(r.body());var done=tickets.get(identity,b.id());assertThat(done.status()).isEqualTo(Status.ISSUED);assertThat(done.reservation()).isEqualTo(Reservation.RAC);assertThat(done.payment()).isEqualTo(Payment.CAPTURED);assertThat(count("rail_provider_operation","reservation_id",b.id())).isEqualTo(1);assertThat(count("payment_operation","payment_id",b.id())).isEqualTo(2);assertThat(count("payment_journal","payment_id",b.id())).isEqualTo(2);assertThat(count("rail_ticket_legacy_proof","booking_id",b.id())).isEqualTo(1);assertThat(count("rail_ticket_review_checkpoint","booking_id",b.id())).isZero();assertThatThrownBy(()->jdbc.sql("update rail_ticket_legacy_proof set proof='{}' where booking_id=:id").param("id",b.id()).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(tickets.timeline(identity,b.id()).stream().map(e->e.eventType())).contains("RailLegacyOutcomeReconciled");}
 @Test void historicalReserveReceiptDoesNotOverrideCurrentCancellation()throws Exception{var issued=finish(book(quote(),Scenario.SUCCESS).id());supplier.cancel(UUID.randomUUID(),issued.id());var b=legacy(issued,true);var r=call("POST","/api/v1/operations/reviews/RAIL/"+b.id()+"/reconcile-legacy",operator("legacy-ops"),key(),Map.of("version",b.version(),"reason","PROVIDER_STATUS_AVAILABLE","consent",true));assertThat(r.statusCode()).isEqualTo(409);assertThat(tickets.get(identity,b.id()).status()).isEqualTo(Status.REVIEW);assertThat(count("rail_ticket_legacy_proof","booking_id",b.id())).isZero();assertThat(count("payment_refund","payment_id",b.id())).isZero();}
 @Test void legacyRefundNeedsVerifiedSettlementAndKeepsTheOriginalEntitlement()throws Exception{var b=finish(book(quote(),Scenario.SUCCESS).id());var q=tickets.cancellationQuote(identity,b.id(),key(),correlation());tickets.cancel(identity,b.id(),q.id(),true,true,false,key(),correlation());worker.tick();worker.tick();var old=legacy(tickets.get(identity,b.id()),false);String path="/api/v1/operations/reviews/RAIL/"+b.id()+"/reconcile-legacy",key=key(),ops=operator("legacy-refund");var body=Map.of("version",old.version(),"reason","PROVIDER_STATUS_AVAILABLE","consent",true);assertThat(call("POST",path,ops,key,body).statusCode()).isEqualTo(409);clock.now=clock.now.plusSeconds(6);assertThat(refunds.settleNext()).isTrue();var r=call("POST",path,ops,key,body);assertThat(r.statusCode()).as(r.body()).isEqualTo(202);var done=tickets.get(identity,b.id());assertThat(done.status()).isEqualTo(Status.CANCELLED);assertThat(done.refund()).isEqualTo(Refund.SUCCEEDED);assertThat(done.cancellation().quote().refundAmount()).isEqualTo(q.refundAmount());assertThat(count("payment_refund","payment_id",b.id())).isEqualTo(1);assertThat(count("payment_refund_journal","operation_id",done.operation(Step.REFUND))).isEqualTo(2);assertThat(tickets.cancellations(identity,b.id())).hasSize(1);}
 @Test void legacyProofAndAuditRollBackWithTheOutbox(){var b=legacy(finish(book(quote(),Scenario.SUCCESS).id()),true);jdbc.sql("create function fail_legacy_event() returns trigger language plpgsql as $$ begin raise exception 'Injected legacy event failure'; end $$").update();jdbc.sql("create trigger fail_legacy_event before insert on rail_ticket_outbox for each row execute function fail_legacy_event()").update();try{assertThatThrownBy(()->operations.reconcileLegacy(com.travbook.shared.domain.Recovery.Kind.RAIL,b.id(),b.version(),"a".repeat(64),com.travbook.shared.domain.Recovery.Reason.PROVIDER_STATUS_AVAILABLE,true,key(),correlation())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(tickets.get(identity,b.id()).version()).isEqualTo(b.version());assertThat(count("rail_ticket_recovery_action","booking_id",b.id())).isZero();assertThat(count("rail_ticket_legacy_proof","booking_id",b.id())).isZero();assertThat(count("payment_journal","payment_id",b.id())).isEqualTo(2);}finally{jdbc.sql("drop trigger fail_legacy_event on rail_ticket_outbox").update();jdbc.sql("drop function fail_legacy_event()").update();}}
}
